// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.bitwise;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigInteger;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.BITF;
import org.eclipse.rdf4j.model.vocabulary.ENCF;
import org.eclipse.rdf4j.model.vocabulary.MISCF;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.eclipse.rdf4j.query.algebra.evaluation.function.encoding.Base64Decode;
import org.eclipse.rdf4j.query.algebra.evaluation.function.encoding.Base64Encode;
import org.eclipse.rdf4j.query.algebra.evaluation.function.encoding.Crc32;
import org.eclipse.rdf4j.query.algebra.evaluation.function.encoding.FromHex;
import org.eclipse.rdf4j.query.algebra.evaluation.function.encoding.Hmac;
import org.eclipse.rdf4j.query.algebra.evaluation.function.encoding.ToHex;
import org.eclipse.rdf4j.query.algebra.evaluation.function.encoding.XxHash64;
import org.eclipse.rdf4j.query.algebra.evaluation.function.misc.NullIf;
import org.junit.jupiter.api.Test;

class BitwiseEncodingMiscFunctionsTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static Literal integer(long v) {
		return VF.createLiteral(BigInteger.valueOf(v));
	}

	private static Literal str(String s) {
		return VF.createLiteral(s);
	}

	@Test
	void bitwise() {
		assertThat(new BitAnd().evaluate(VF, integer(12), integer(10))).isEqualTo(integer(8));
		assertThat(new BitOr().evaluate(VF, integer(12), integer(10))).isEqualTo(integer(14));
		assertThat(new BitXor().evaluate(VF, integer(12), integer(10))).isEqualTo(integer(6));
		assertThat(new BitNot().evaluate(VF, integer(0))).isEqualTo(integer(-1));
		assertThat(new BitCount().evaluate(VF, integer(255))).isEqualTo(integer(8));
		assertThat(new BitCount().evaluate(VF, integer(-1))).isEqualTo(integer(64));
		assertThat(new BitCount().evaluate(VF, VF.createLiteral(BigInteger.TWO.pow(100))))
				.isEqualTo(integer(1));
		// negative values are counted as 64-bit two's complement, like toHex; wider negatives are an error rather
		// than silently switching to another definition
		assertThat(new BitCount().evaluate(VF, integer(Long.MIN_VALUE))).isEqualTo(integer(1));
		assertThatThrownBy(() -> new BitCount().evaluate(VF,
				VF.createLiteral(BigInteger.TWO.pow(64).negate().subtract(BigInteger.ONE))))
						.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new BitShiftLeft().evaluate(VF, integer(1), integer(70)))
				.isEqualTo(VF.createLiteral(BigInteger.TWO.pow(70)));
		assertThat(new BitShiftRight().evaluate(VF, integer(-16), integer(2))).isEqualTo(integer(-4));
		assertThatThrownBy(() -> new BitAnd().evaluate(VF, integer(1), VF.createLiteral(1.5)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new BitShiftLeft().evaluate(VF, integer(1), VF.createLiteral(BigInteger.TWO.pow(40))))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void encoding() {
		assertThat(new Base64Encode().evaluate(VF, str("hello"))).isEqualTo(str("aGVsbG8="));
		assertThat(new Base64Encode().evaluate(VF, VF.createLiteral("68656c6c6f", CoreDatatype.XSD.HEXBINARY)))
				.isEqualTo(str("aGVsbG8="));
		assertThat(new Base64Decode().evaluate(VF, str("aGVsbG8="))).isEqualTo(str("hello"));
		assertThat(new Base64Decode().evaluate(VF, str("aGVsbG8"))).isEqualTo(str("hello"));
		assertThatThrownBy(() -> new Base64Decode().evaluate(VF, str("%%%")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Base64Decode().evaluate(VF, str("/w==")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new ToHex().evaluate(VF, integer(255))).isEqualTo(str("ff"));
		assertThat(new ToHex().evaluate(VF, integer(-1))).isEqualTo(str("ffffffffffffffff"));
		assertThat(new ToHex().evaluate(VF, str("hi"))).isEqualTo(str("6869"));
		assertThat(new FromHex().evaluate(VF, str("6869"))).isEqualTo(str("hi"));
		assertThatThrownBy(() -> new FromHex().evaluate(VF, str("abc")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new Crc32().evaluate(VF, str("hello"))).isEqualTo(integer(907060870L));
		assertThat(new XxHash64().evaluate(VF, str("")))
				.isEqualTo(VF.createLiteral(new BigInteger("17241709254077376921")));
		assertThat(new XxHash64().evaluate(VF, str("a")))
				.isEqualTo(VF.createLiteral(new BigInteger("15154266338359012955")));
		assertThat(XxHash64.hash("The quick brown fox jumps over the lazy dog".getBytes(), 0))
				.isEqualTo(0x0B242D361FDA71BCL);
		assertThat(new Hmac().evaluate(VF, str("The quick brown fox jumps over the lazy dog"), str("key")))
				.isEqualTo(str("f7bc83f430538424b13298e6aa6fb143ef4d59a14946175997479dbc2d1a3cd8"));
		assertThat(new Hmac().evaluate(VF, str("The quick brown fox jumps over the lazy dog"), str("key"), str("md5")))
				.isEqualTo(str("80070713463e7749b90c2dc24911e275"));
		assertThatThrownBy(() -> new Hmac().evaluate(VF, str("x"), str("k"), str("rot13")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void nullIf() {
		assertThat(new NullIf().evaluate(VF, integer(1), integer(2))).isEqualTo(integer(1));
		assertThatThrownBy(() -> new NullIf().evaluate(VF, integer(1), VF.createLiteral(1.0)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new NullIf().evaluate(VF, VF.createIRI("urn:a"), VF.createIRI("urn:a")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new NullIf().evaluate(VF, VF.createIRI("urn:a"), str("x"))).isEqualTo(VF.createIRI("urn:a"));
	}

	@Test
	void allRegistered() {
		FunctionRegistry registry = FunctionRegistry.getInstance();
		for (String name : new String[] { "bitAnd", "bitOr", "bitXor", "bitNot", "bitCount", "bitShiftLeft",
				"bitShiftRight" }) {
			assertThat(registry.get(BITF.NAMESPACE + name)).as(name).isPresent();
		}
		for (String name : new String[] { "base64Encode", "base64Decode", "toHex", "fromHex", "crc32", "xxhash64",
				"hmac" }) {
			assertThat(registry.get(ENCF.NAMESPACE + name)).as(name).isPresent();
		}
		assertThat(registry.get(MISCF.NAMESPACE + "nullIf")).isPresent();
	}
}
